CREATE TABLE t1(a INTEGER PRIMARY KEY,w INT GENERATED ALWAYS AS (a*10),b TEXT,x TEXT AS (typeof(c)),y TEXT AS (substr(b,a,a+2)) STORED,c ANY); INSERT INTO t1(a,b,c) VALUES(1,'abcdef',5.5),(3,'cantaloupe',NULL); CREATE INDEX t1w ON t1(w); CREATE INDEX t1x ON t1(x) WHERE w BETWEEN 20 AND 40; UPDATE t1 SET a=a+100 WHERE w<20;